import os
import subprocess
import tempfile
from flask import Flask, request, jsonify

app = Flask(__name__)

UPLOAD_DIR = '/tmp/uploads'
os.makedirs(UPLOAD_DIR, exist_ok=True)

def sanitize_filename(name):
    # Remove path traversal attempts
    name = name.replace('..', '').replace('/', '').replace('\\', '')
    return name

def convert_document(input_path, output_format):
    """Convert document using LibreOffice headless mode"""
    output_dir = tempfile.mkdtemp(prefix='conv_')
    cmd = f'libreoffice --headless --convert-to {output_format} --outdir {output_dir} {input_path}'
    result = subprocess.run(cmd, shell=True, capture_output=True, timeout=30)
    if result.returncode != 0:
        raise RuntimeError(f'Conversion failed: {result.stderr.decode()}')
    return output_dir

@app.route('/api/convert', methods=['POST'])
def handle_convert():
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    uploaded = request.files['file']
    output_format = request.form.get('format', 'pdf')

    # Validate output format
    allowed_formats = ['pdf', 'docx', 'xlsx', 'pptx', 'odt', 'html', 'txt']
    if output_format not in allowed_formats:
        return jsonify({'error': 'Invalid format'}), 400

    filename = sanitize_filename(uploaded.filename)
    if not filename:
        return jsonify({'error': 'Invalid filename'}), 400

    input_path = os.path.join(UPLOAD_DIR, filename)
    uploaded.save(input_path)

    try:
        output_dir = convert_document(input_path, output_format)
        # Return first converted file
        converted_files = os.listdir(output_dir)
        if not converted_files:
            return jsonify({'error': 'No output generated'}), 500

        converted_path = os.path.join(output_dir, converted_files[0])
        with open(converted_path, 'rb') as f:
            content = f.read()

        return content, 200, {'Content-Type': 'application/octet-stream',
                               'Content-Disposition': f'attachment; filename={converted_files[0]}'}
    except Exception as e:
        return jsonify({'error': str(e)}), 500
    finally:
        if os.path.exists(input_path):
            os.unlink(input_path)

@app.route('/api/metadata', methods=['POST'])
def handle_metadata():
    """Extract metadata from uploaded document"""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    uploaded = request.files['file']
    filename = sanitize_filename(uploaded.filename)
    input_path = os.path.join(UPLOAD_DIR, filename)
    uploaded.save(input_path)

    try:
        # Use exiftool for metadata extraction
        cmd = ['exiftool', '-json', input_path]
        result = subprocess.run(cmd, capture_output=True, timeout=10)
        metadata = result.stdout.decode()
        return metadata, 200, {'Content-Type': 'application/json'}
    except Exception as e:
        return jsonify({'error': str(e)}), 500
    finally:
        if os.path.exists(input_path):
            os.unlink(input_path)

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
